//! 🌳️ Genuine committed graph rows supply checkpoint provenance and inactive scoped publication.
use crate::*;
type Publisher=store::os_store::original_replay_publication::OriginalReplayPublication<State,Mutation>;
fn policy()->RetainedCloneGrant{RetainedCloneGrant{maximum_copy_bytes:32768,maximum_capacity_bytes:16<<20,..TURN}}
fn existing_report(store:&mut store::ConfigStore<State,Mutation>,zoom:f64,caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner)->store::os_store::replay::EditReplayResult<State,Mutation>{let id=store.parts_ref().log.envelope.vcs.edits.get(0).unwrap().mutation_meta[0].mutation_id.clone().unwrap();let drafts=protocol::HistoryInputDrafts::from([(id,protocol::InputReplacement::Input{schema:String::from("test.window.genesis"),payload:format!("op{{\"kind\":\"zoom\",\"zoom\":{zoom}}}").into_bytes()})]);let mut replay=Some(store.begin_derived_report_replay(drafts,None).unwrap());for index in 0..262144{let ready=turn(caller,decoder,policy(),|cx|{let grant=cx.retained_grant();let result=cx.with_native_receiving(|native|store.step_derived_report_replay(replay.as_mut().unwrap(),grant,native,&mut||false));let p=replay.as_mut().unwrap().take_preparation_receipt();if let Some(issued)=cx.receiving_issued_grant(){cx.consume_receiving_retained(issued,p)?;}else{cx.consume_retained(p)?;}cx.consume_fuel(p.copied_items as u64);Ok(matches!(result.unwrap(),store::os_store::replay::ReplayStep::Finished(_)))});if ready{break}assert!(index<262143);}let(result,head)=store.finish_derived_report_replay(&mut replay).unwrap();drop(head);assert!(replay.is_none());result}
fn publish(store:&mut store::ConfigStore<State,Mutation>,result:store::os_store::replay::EditReplayResult<State,Mutation>,request:store::HistoryFinalization,applies:bool,caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner){let before=store.snapshot().unwrap().zoom;let generation=store.generation();let revision=store.content_revision();let count=store.parts_ref().log.envelope.transitions.len();let mut result=Some(result);let mut request=Some(request);let mut owner=None;turn(caller,decoder,policy(),|cx|{assert!(Publisher::admit(store,&mut result,&mut request,cx,&mut owner)?);Ok(())});let source=owner.as_mut().unwrap();for index in 0..262144{let ready=turn(caller,decoder,policy(),|cx|source.advance(store,cx));assert_eq!(store.snapshot().unwrap().zoom,before);assert_eq!(store.parts_ref().log.envelope.transitions.len(),count);if ready{break}assert!(index<262143);}assert!(source.prepared());turn(caller,decoder,policy(),|cx|{assert!(source.publish(store,cx)?);Ok(())});assert_eq!(store.generation(),generation+1);if !applies{assert_eq!(store.snapshot().unwrap().zoom,before);assert_eq!(store.content_revision(),revision);}let mut receipt=None;turn(caller,decoder,policy(),|cx|{assert!(source.take_receipt(cx,&mut receipt)?);Ok(())});assert_eq!(receipt.unwrap().applies_to_head,applies);turn(caller,decoder,policy(),|cx|{assert!(source.acknowledge(cx)?);Ok(())});for index in 0..262144{if turn(caller,decoder,policy(),|cx|cx.with_original_retirement(|cx|source.close_step(store,cx))){break}assert!(index<262143);}assert!(source.terminal_is_empty());turn(caller,decoder,policy(),|cx|cx.with_original_retirement(|cx|{let d=Publisher::boxed_release_demands();close_original_retained_step(cx,d,|_|{drop(owner.take());Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,released_bytes:d.release_bytes,..Default::default()}))})?;Ok(())}));}
#[test]
fn native_existing_checkpoint_origins_and_inactive_scope_preserve_current_head(){let law:serde_json::Value=serde_json::from_str(include_str!("../../../../../../../../🧰️framework/🛍️products/💻️os/🔨️modules/🏪️store/⚙️engine/🌿️branch/📜️transitions/existing.json")).unwrap();let mut caller=caller();let mut decoder=OriginalJobDecodeOwner::empty();let mut store=native_document_store(&mut caller,&mut decoder);let result=crate::original_replay_publication::prepare_report(&mut store,&mut caller,&mut decoder);publish(&mut store,result,store::HistoryFinalization::Alternative{name:law["firstName"].as_str().unwrap().into()},true,&mut caller,&mut decoder);assert_eq!(store.snapshot().unwrap().zoom,law["firstHead"].as_f64().unwrap());assert_eq!(store.parts_ref().log.envelope.transitions.len(),law["expectedTransitions"][0].as_u64().unwrap()as usize);repin_metadata::exercise(&store,&mut caller,&mut decoder);let first=store.parts_ref().log.envelope.active_alternative_id.clone().unwrap();let checkpoint=store.parts_ref().log.current_checkpoint_id.as_deref().unwrap().to_owned();let original_commit=store.parts_ref().log.envelope.transitions.get(0).unwrap().mutation_id.clone();let result=existing_report(&mut store,law["secondHead"].as_f64().unwrap(),&mut caller,&mut decoder);publish(&mut store,result,store::HistoryFinalization::Alternative{name:law["secondName"].as_str().unwrap().into()},true,&mut caller,&mut decoder);assert_eq!(store.snapshot().unwrap().zoom,law["secondHead"].as_f64().unwrap());assert_eq!(store.parts_ref().log.envelope.transitions.len(),law["expectedTransitions"][1].as_u64().unwrap()as usize);assert_eq!(store.parts_ref().log.current_checkpoint_id.as_deref(),Some(checkpoint.as_str()));assert_eq!(store.parts_ref().log.envelope.vcs.checkpoints.len(),1);assert_eq!(store.parts_ref().log.envelope.vcs.alternatives.len(),2);assert_eq!(store.parts_ref().log.envelope.transitions.get(3).unwrap().dependencies,[original_commit]);for(index,scope)in law["scopes"].as_array().unwrap().iter().enumerate(){let scope=match scope.as_str().unwrap(){"trunk"=>store.trunk_alternative_id(),"firstAlternative"=>first.clone(),_=>unreachable!()};let result=existing_report(&mut store,law["inactiveReplacement"].as_f64().unwrap(),&mut caller,&mut decoder);publish(&mut store,result,store::HistoryFinalization::Scope{alternative_id:scope},false,&mut caller,&mut decoder);assert_eq!(store.snapshot().unwrap().zoom,law["secondHead"].as_f64().unwrap());assert_eq!(store.parts_ref().log.envelope.transitions.len(),law["expectedTransitions"][index+2].as_u64().unwrap()as usize);}for index in 0..1048576{if store.close_owned_store_terminal_is_empty(){break}turn(&mut caller,&mut decoder,policy(),|cx|cx.with_original_retirement(|cx|{let d=store.close_owned_demands(4096)?;close_original_retained_step(cx,d,|grant|store.close_owned_store_step(grant))?;Ok(())}));assert!(index<1048575);}release_native_store_box(store,&mut caller,&mut decoder);while !decoder.terminal_is_empty(){caller.turn(policy(),|cx|cx.with_original_retirement(|cx|{let d=decoder.retirement_demands(4096)?;close_original_retained_step(cx,d,|grant|decoder.close_step(grant))?;Ok(())})).unwrap();}caller.retire(policy());}

#[path="transition-repin.rs"]
mod repin_metadata;

fn repin_denials(d:RetirementDemand)->Vec<RetainedCloneGrant>{let full=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth};let mut out=Vec::new();for axis in 0..5{let amount=match axis{0=>1,1=>d.copy_bytes,2=>d.capacity_bytes,3=>d.release_bytes,_=>d.depth};if amount==0{continue}let mut denied=full;match axis{0=>denied.maximum_items=0,1=>denied.maximum_copy_bytes-=1,2=>denied.maximum_capacity_bytes-=1,3=>denied.maximum_release_bytes-=1,_=>denied.maximum_depth-=1}out.push(denied);}out}

#[test]
fn native_repin_publishes_graph_atomically_without_replaying_the_artifact(){
 type Repin=store::os_store::original_replay_publication::repin::OriginalRepinPublication<Mutation>;
 for cut in [Some(0),Some(1),Some(8),Some(32),Some(128),Some(512),None]{
  let mut caller=caller();let mut decoder=OriginalJobDecodeOwner::empty();let mut store=native_document_store(&mut caller,&mut decoder);let result=crate::original_replay_publication::prepare_report(&mut store,&mut caller,&mut decoder);publish(&mut store,result,store::HistoryFinalization::Alternative{name:"Pinned Alternative".into()},true,&mut caller,&mut decoder);
  let key=store.parts_ref().log.envelope.vcs.checkpoints.key_at(0).unwrap();let old=store.parts_ref().log.envelope.vcs.checkpoints.get_key(key).unwrap().id.clone();let generation=store.generation();let revision=store.content_revision();let count=store.parts_ref().log.envelope.transitions.len();let state=store.snapshot_ref()as*const State;let zoom=store.snapshot_ref().zoom;
  let mut pins=None;turn(&mut caller,&mut decoder,policy(),|cx|{let capacity=size_of::<store::os_vcs::CompositionPin>()+"childenergy.energy1*ck-child".len();let d=OriginalConstructionDemand{items:1,copy_bytes:512,capacity_bytes:capacity,release_bytes:0,depth:1};admit_original_construction(cx,&mut pins,d,|_|Ok((vec![store::os_vcs::CompositionPin{child_ref:semio_framework_artifact_reference::ArtifactRef{artifact_id:"child".into(),dialect:semio_framework_artifact_reference::ArtifactDialect{artifact_kind:"energy.energy".into(),standard:"1".into(),subset:"*".into()}},checkpoint_id:"ck-child".into()}],RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,retained_capacity_bytes:capacity,..Default::default()})))?;Ok(())});let pointer=pins.as_ref().unwrap().as_ptr();let mut owner=None;let d=Repin::capture_demands();assert!(d.copy_bytes<=32768&&d.capacity_bytes<=16<<20);for denied in repin_denials(d){turn(&mut caller,&mut decoder,denied,|cx|{assert!(!Repin::admit(&store,key,&mut pins,cx,&mut owner)?);assert_eq!(pins.as_ref().unwrap().as_ptr(),pointer);assert!(owner.is_none());Ok(())});}turn(&mut caller,&mut decoder,policy(),|cx|{if cut.is_none(){assert!(Repin::admit_current(&store,&mut pins,cx,&mut owner)?);}else{assert!(Repin::admit(&store,key,&mut pins,cx,&mut owner)?);}Ok(())});assert!(pins.is_none());let mut foreign=OriginalJobDecodeOwner::empty();turn(&mut caller,&mut foreign,policy(),|cx|{assert!(owner.as_mut().unwrap().advance(&mut store,cx).is_err());assert!(owner.as_mut().unwrap().close_step(&mut store,4096,cx).is_err());Ok(())});assert!(foreign.terminal_is_empty());
  for index in 0..262144{if cut==Some(index){break}let ready=turn(&mut caller,&mut decoder,policy(),|cx|owner.as_mut().unwrap().advance(&mut store,cx));assert_eq!(store.generation(),generation);assert_eq!(store.content_revision(),revision);assert_eq!(store.parts_ref().log.envelope.transitions.len(),count);assert_eq!(store.parts_ref().log.envelope.vcs.checkpoints.get_key(key).unwrap().id,old);assert_eq!(store.snapshot_ref()as*const State,state);if ready{break}assert!(index<262143);}
  if cut.is_none(){assert!(owner.as_ref().unwrap().prepared());turn(&mut caller,&mut decoder,policy(),|cx|{assert!(owner.as_mut().unwrap().publish(&mut store,cx)?);Ok(())});assert_eq!(store.generation(),generation+1);assert_eq!(store.parts_ref().log.envelope.transitions.len(),count+1);let checkpoint=store.parts_ref().log.envelope.vcs.checkpoints.get_key(key).unwrap();assert_ne!(checkpoint.id,old);assert_eq!(checkpoint.composition_pins.as_ptr(),pointer);assert_eq!(store.parts_ref().log.current_checkpoint_id.as_deref(),Some(checkpoint.id.as_str()));assert!(store.parts_ref().log.envelope.vcs.alternatives.iter().all(|alternative|!alternative.checkpoint_ids.contains(&old)));assert_eq!(store.snapshot_ref()as*const State,state);assert_eq!(store.snapshot_ref().zoom,zoom);}
  for index in 0..1048576{if owner.as_ref().unwrap().terminal_is_empty(){break}let d=owner.as_ref().unwrap().close_demands(&store,4096).unwrap();for denied in repin_denials(d){turn(&mut caller,&mut decoder,denied,|cx|cx.with_original_retirement(|cx|{let before=cx.retained_progress();assert!(!owner.as_mut().unwrap().close_step(&mut store,4096,cx)?);assert_eq!(cx.retained_progress(),before);Ok(())}));assert_eq!(owner.as_ref().unwrap().close_demands(&store,4096).unwrap(),d);}let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth};turn(&mut caller,&mut decoder,grant,|cx|cx.with_original_retirement(|cx|owner.as_mut().unwrap().close_step(&mut store,4096,cx)));assert!(index<1048575);}
  if cut.is_some(){assert_eq!(store.generation(),generation);assert_eq!(store.content_revision(),revision);assert_eq!(store.parts_ref().log.envelope.vcs.checkpoints.get_key(key).unwrap().id,old);}assert!(store.parts_ref().log.envelope.vcs.checkpoints.replacement_group_identity().is_none());assert!(store.parts_ref().log.envelope.vcs.alternatives.replacement_group_identity().is_none());turn(&mut caller,&mut decoder,policy(),|cx|cx.with_original_retirement(|cx|{let d=Repin::boxed_release_demands();close_original_retained_step(cx,d,|_|{owner=None;Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,released_bytes:d.release_bytes,..Default::default()}))})?;Ok(())}));
  for index in 0..1048576{if store.close_owned_store_terminal_is_empty(){break}turn(&mut caller,&mut decoder,policy(),|cx|cx.with_original_retirement(|cx|{let d=store.close_owned_demands(4096)?;close_original_retained_step(cx,d,|grant|store.close_owned_store_step(grant))?;Ok(())}));assert!(index<1048575);}release_native_store_box(store,&mut caller,&mut decoder);while !decoder.terminal_is_empty(){caller.turn(policy(),|cx|cx.with_original_retirement(|cx|{let d=decoder.retirement_demands(4096)?;close_original_retained_step(cx,d,|grant|decoder.close_step(grant))?;Ok(())})).unwrap();}caller.retire(policy());
 }
}

#[test]
fn native_checkpoint_checkout_folds_actual_selected_alternative_scope(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("../../../../../../../../🧰️framework/🛍️products/💻️os/🔨️modules/🏪️store/🕰️history/🏁️replay/checkout.json")).unwrap();let mut caller=caller();let mut decoder=OriginalJobDecodeOwner::empty();let mut store=native_document_store(&mut caller,&mut decoder);let result=crate::original_replay_publication::prepare_report(&mut store,&mut caller,&mut decoder);publish(&mut store,result,store::HistoryFinalization::Alternative{name:fixture["scoped"]["alternative"].as_str().unwrap().into()},true,&mut caller,&mut decoder);let expected=store.snapshot().unwrap().zoom;assert_eq!(expected,fixture["scoped"]["visibleAfter"].as_f64().unwrap());let line=store.parts_ref().log.envelope.active_alternative_id.as_ref().unwrap().clone();let mut id=None;turn(&mut caller,&mut decoder,policy(),|cx|{let value=store.current_checkpoint_id().unwrap();let d=OriginalConstructionDemand{items:1,copy_bytes:value.len()+size_of::<String>(),capacity_bytes:value.len(),release_bytes:0,depth:1};admit_original_construction(cx,&mut id,d,|_|Ok((value.to_owned(),RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,retained_capacity_bytes:d.capacity_bytes,..Default::default()})))?;Ok(())});crate::original_checkpoint_checkout::exercise_scoped_checkout(&mut store,&mut caller,&mut decoder,id.unwrap(),expected);assert_eq!(store.parts_ref().log.envelope.active_alternative_id.as_deref(),Some(line.as_str()));for index in 0..1048576{if store.close_owned_store_terminal_is_empty(){break}turn(&mut caller,&mut decoder,policy(),|cx|cx.with_original_retirement(|cx|{let d=store.close_owned_demands(4096)?;close_original_retained_step(cx,d,|grant|store.close_owned_store_step(grant))?;Ok(())}));assert!(index<1048575);}release_native_store_box(store,&mut caller,&mut decoder);while !decoder.terminal_is_empty(){caller.turn(policy(),|cx|cx.with_original_retirement(|cx|{let d=decoder.retirement_demands(4096)?;close_original_retained_step(cx,d,|grant|decoder.close_step(grant))?;Ok(())})).unwrap();}caller.retire(policy());
}
